using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Runtime.Serialization.Json;
using System.Windows;
using System.Windows.Automation;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace MaohaiziPet {
public static class DesktopPlayTests {
    static LivingReport report;
    static void Assert(bool ok,string reason){if(!ok)throw new Exception(reason);}
    static void Check(string name,Action run){var item=new TestResult{name=name};try{run();item.passed=true;report.passed++;}catch(Exception e){item.error=e.ToString();report.failed++;}report.tests.Add(item);}
    static IEnumerable<Button> Buttons(DependencyObject root){for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);if(child is Button)yield return (Button)child;foreach(var b in Buttons(child))yield return b;}}
    static void Click(FrameworkElement root,string name){Buttons(root).Single(b=>AutomationProperties.GetName(b)==name).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
    static void Layout(FrameworkElement content){content.Measure(new Size(324,900));content.Arrange(new Rect(new Point(),content.DesiredSize));content.UpdateLayout();}
    static void Render(FrameworkElement content,string path){Layout(content);var image=new RenderTargetBitmap((int)content.ActualWidth*2,(int)Math.Ceiling(content.ActualHeight)*2,192,192,PixelFormats.Pbgra32);image.Render(content);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(image));using(var file=File.Create(path))png.Save(file);}
    public static int Run(string manifest,string output){
        Directory.CreateDirectory(output);PetSettings.UsePreviewProfile(Path.Combine(output,"isolated-state"));report=new LivingReport{scope="Desktop-only petting versus drag intent, toy pocket routing, missing motion gates, quiet/focus/cooldown and actual WPF layout"};
        Check("按住头顶、下巴或左右脸大幅移动也不会拖走猫咪",delegate{foreach(var zone in new[]{PetTouchZone.Head,PetTouchZone.Chin,PetTouchZone.CheekLeft,PetTouchZone.CheekRight}){var p=new PetPointerPress();p.Begin(zone,new Point(100,100),false,true);p.Move(new Point(380,450));Assert(p.Held&&p.Stroking&&!p.Dragging,"抚摸变成拖动："+zone);}});
        Check("按身体和爪子需越过拖动阈值，轻点仍可互动",delegate{foreach(var zone in new[]{PetTouchZone.Back,PetTouchZone.PawLeft,PetTouchZone.PawRight,PetTouchZone.Nose}){var p=new PetPointerPress();p.Begin(zone,new Point(100,100),false,true);p.Move(new Point(106,108));Assert(!p.Dragging&&!p.Stroking,"轻点提前拖动");p.Move(new Point(112,100));Assert(p.Dragging,"身体不能拖动");}});
        Check("拿着玩具时移动不拖猫，工具中途失效也不改意图",delegate{var p=new PetPointerPress();p.Begin(PetTouchZone.Head,new Point(),true,true);p.Move(new Point(500,500));Assert(p.Tool&&!p.Stroking&&!p.Dragging,"拿工具误摸或拖猫");});
        Check("释放或失去捕获会清空按压意图，下一次从新部位开始",delegate{var p=new PetPointerPress();p.Begin(PetTouchZone.Back,new Point(),false,true);p.Move(new Point(50,0));p.End();Assert(!p.Held&&!p.Dragging&&!p.Tool&&!p.Stroking,"按压未释放");p.Move(new Point(90,0));Assert(!p.Dragging,"松手后继续拖");p.Begin(PetTouchZone.Chin,new Point(),false,true);Assert(p.Stroking&&!p.Dragging,"新按压继承旧状态");});
        Check("旧版卡通角色保留原拖动操作",delegate{var p=new PetPointerPress();p.Begin(PetTouchZone.Head,new Point(),false,false);p.Move(new Point(12,0));Assert(p.Dragging&&!p.Stroking,"影响旧角色");});
        Check("轮滚抚摸只用于连续部位，不重复抽动鼻尖和爪子",delegate{foreach(var zone in new[]{PetTouchZone.Head,PetTouchZone.Chin,PetTouchZone.Back,PetTouchZone.CheekLeft,PetTouchZone.CheekRight})Assert(PetTouchMap.Continuous(zone),"缺少可挠部位");foreach(var zone in new[]{PetTouchZone.Nose,PetTouchZone.PawLeft,PetTouchZone.PawRight,PetTouchZone.None})Assert(!PetTouchMap.Continuous(zone),"离散动作被轮滚重播");});
        var app=new Application();var c=new PetController(app);c.Skin=PetSkin.Load(manifest);c.Settings.Mode=PetMode.Companion;c.Engine.SetMode(PetMode.Companion);c.Settings.Size=180;
        c.ConfigureMotions();
        c.Pet=new PetWindow(c);c.Pet.Surface.Measure(new Size(c.Pet.Width,c.Pet.Height));c.Pet.Surface.Arrange(new Rect(0,0,c.Pet.Width,c.Pet.Height));
        Check("扩大透明画布保留原来的猫咪位置，并容纳最大尺寸的完整动作",delegate{var area=SystemParameters.WorkArea;double expectedLeft=double.IsNaN(c.Settings.Left)?area.Right-400:c.Settings.Left,expectedTop=double.IsNaN(c.Settings.Top)?area.Bottom-310:c.Settings.Top;Assert(Math.Abs(c.Pet.Left+(c.Pet.Width-360)/2-expectedLeft)<.001&&Math.Abs(c.Pet.Top+c.Pet.Height-300-expectedTop)<.001,"透明画布改变了原位置");double oldSize=c.Settings.Size;c.Settings.Size=240;Rect r=c.Pet.Surface.PetRect;foreach(var clip in c.Skin.Motions.Clips.Values){if(clip.Spec.id=="sit-jump")continue; // JumpPlayTests checks actual alpha bounds, not transparent canvas padding.
double left=r.X+clip.Spec.originX*240/256,top=r.Y+clip.Spec.originY*240/256;Assert(left>=0&&left+clip.Size*240/256<=c.Pet.Width&&top>=0&&r.Y+235*240/256<c.Pet.Height,"最大尺寸的动作被窗口裁切："+clip.Spec.id);}c.Settings.Size=oldSize;});
        Check("所有可用互动可直接在桌面展开且不创建设置窗",delegate{var pocket=new DesktopPetPocket(c);Render(pocket.Content,Path.Combine(output,"desktop-pocket.png"));foreach(DesktopPetAction action in Enum.GetValues(typeof(DesktopPetAction)))Assert(Buttons(pocket.Content).Any(b=>AutomationProperties.GetName(b)==DesktopPetPocket.Label(action))==c.HasDesktopAction(action),"可用入口缺失或未完成动作泄漏");Assert(pocket.Content.ActualHeight<475&&pocket.Content.ActualWidth==324,"菜单尺寸过大或溢出");foreach(var b in Buttons(pocket.Content)){Assert(b.ActualWidth>0&&b.ActualHeight>0,"按钮不可见");Assert(b.DesiredSize.Height-b.Margin.Top-b.Margin.Bottom<=b.ActualHeight+.5,"按钮裁切");}Assert(c.Panel==null,"创建了设置窗");});
        Check("点击桌面羽毛和毛刷入口直接拿起工具",delegate{foreach(var action in new[]{DesktopPetAction.Feather,DesktopPetAction.Brush}){var pocket=new DesktopPetPocket(c);Layout(pocket.Content);Click(pocket.Content,DesktopPetPocket.Label(action));Assert(c.Life.Play.Tool==(action==DesktopPetAction.Feather?PetTool.Feather:PetTool.Brush)&&c.Life.Play.Active,"入口未绑定实际工具");Assert(c.Panel==null,"拿玩具依赖设置窗");}c.SelectTool(PetTool.Hand);});
        Check("毛线球进入真实可操作会话，陪伴入口仍保留",delegate{Assert(c.DoDesktopAction(DesktopPetAction.Yarn)&&c.Life.Play.Tool==PetTool.Yarn&&c.Companion.Gesture==CompanionGesture.None,"毛线球仍是固定动画");Assert(c.Panel==null,"玩球打开设置窗");c.SelectTool(PetTool.Hand);Assert(c.DoDesktopAction(DesktopPetAction.Comfort)&&c.Companion.Gesture==CompanionGesture.Comfort,"陪伴入口失效");});
        Check("桌面喂食写入实际记录，冷却内按钮禁用且不可绕过",delegate{int count=c.Life.Record.Treats;Assert(c.DoDesktopAction(DesktopPetAction.Treat)&&c.Life.Record.Treats==count+1,"零食未记录");Assert(!c.CanDesktopAction(DesktopPetAction.Treat)&&!c.DoDesktopAction(DesktopPetAction.Treat),"绕过冷却");var pocket=new DesktopPetPocket(c);Layout(pocket.Content);Assert(!Buttons(pocket.Content).Single(b=>AutomationProperties.GetName(b)=="小鱼零食").IsEnabled,"冷却按钮未禁用");c.Life.Tick(11,true,false,DateTime.Now);Assert(c.CanDesktopAction(DesktopPetAction.Treat),"冷却后仍不可用");});
        Check("桌面姿态入口使用已验收动作，重复当前动作不重启",delegate{foreach(var pair in new[]{new KeyValuePair<DesktopPetAction,CatHabit>(DesktopPetAction.Sit,CatHabit.SitUp),new KeyValuePair<DesktopPetAction,CatHabit>(DesktopPetAction.Stand,CatHabit.StandUp),new KeyValuePair<DesktopPetAction,CatHabit>(DesktopPetAction.Groom,CatHabit.Groom),new KeyValuePair<DesktopPetAction,CatHabit>(DesktopPetAction.Yawn,CatHabit.Yawn)}){Assert(c.DoDesktopAction(pair.Key)&&c.Habits.Current==pair.Value,"动作未发起："+pair.Key);int revision=c.Habits.Revision;Assert(!c.DoDesktopAction(pair.Key)&&c.Habits.Revision==revision,"重复动作被重启");}Assert(c.Panel==null,"姿态依赖面板");});
        Check("切换完整动作时等收尾结束后才开始新动作计时",delegate{c.Habits.Interrupt();c.Skin.Motion.Cancel();for(int i=0;i<200&&c.Skin.Motion.Active;i++)c.AdvanceMotions(.05);c.StartHabit(CatHabit.Groom);c.AdvanceMotions(.7);Assert(c.Skin.Motion.Active,"前一个动作没有播放");c.StartHabit(CatHabit.Yawn);Assert(!c.Habits.Active&&c.Skin.Motion.Recovering,"没有等待收尾");for(int i=0;i<200&&c.Skin.Motion.Active;i++)c.AdvanceMotions(.05);Assert(c.Habits.Current==CatHabit.Yawn&&c.Habits.Age==0,"新动作时钟在旧动作收尾期间提前消耗");c.AdvanceMotions(0);Assert(c.Skin.Motion.Active&&c.Skin.Motion.Clip.Spec.id=="yawn"&&c.Skin.Motion.FrameIndex==0,"新动作没有从首帧开始");});
        Check("排队动作遇到专注被取消，不会在收尾后偷偷启动",delegate{c.StartHabit(CatHabit.Groom);Assert(c.Skin.Motion.Recovering,"没有待处理切换");c.ToggleFocus();for(int i=0;i<200&&c.Skin.Motion.Active;i++)c.AdvanceMotions(.05);Assert(!c.Habits.Active&&c.Companion.IsFocusing,"专注期间重新启动了排队动作");c.Companion.CancelFocus();});
        Check("未提供的素材不会出现在菜单里，无效动作被拒绝",delegate{c.Habits.StandReady=false;var pocket=new DesktopPetPocket(c);Layout(pocket.Content);Assert(!c.HasDesktopAction(DesktopPetAction.Stand)&&!c.DoDesktopAction(DesktopPetAction.Stand)&&!Buttons(pocket.Content).Any(b=>AutomationProperties.GetName(b)=="站一会儿"),"无素材仍显示动作");Assert(!c.DoDesktopAction((DesktopPetAction)999),"无效动作被接受");c.Habits.StandReady=true;});
        Check("专注时不启动大姿态，但可以轻轻梳毛",delegate{c.Companion.StartFocus(1500);Assert(!c.CanDesktopAction(DesktopPetAction.Sit)&&!c.DoDesktopAction(DesktopPetAction.Stand),"专注时启动大动作");Assert(c.DoDesktopAction(DesktopPetAction.Brush)&&c.Life.Play.Tool==PetTool.Brush,"专注时不能轻梳毛");c.SelectTool(PetTool.Hand);c.Companion.CancelFocus();});
        Check("勿扰禁用所有互动，桌面恢复入口无需设置窗",delegate{c.Mode(PetMode.Quiet);var pocket=new DesktopPetPocket(c);Render(pocket.Content,Path.Combine(output,"desktop-pocket-quiet.png"));foreach(DesktopPetAction action in Enum.GetValues(typeof(DesktopPetAction)))Assert(!c.CanDesktopAction(action)&&!c.DoDesktopAction(action),"勿扰仍互动");Click(pocket.Content,"恢复陪伴");Assert(c.Engine.Mode==PetMode.Companion&&c.Panel==null,"恢复依赖设置");});
        Check("菜单收起和工具放下后，桌面透明区域继续穿透",delegate{var surface=c.Pet.Surface;var nearby=new Point(surface.PetRect.Left-10,surface.PetRect.Top+20);Assert(!surface.HitPet(nearby),"无工具占用空白");var pocket=new DesktopPetPocket(c);Layout(pocket.Content);pocket.Close();Assert(!surface.HitPet(nearby)&&!surface.HitPet(new Point(2,2)),"菜单影响猫的命中范围");c.DoDesktopAction(DesktopPetAction.Feather);Assert(surface.HitPet(nearby),"工具无法互动");c.SelectTool(PetTool.Hand);Assert(!surface.HitPet(nearby),"放下后仍捕获空白");});
        if(c.Skin.Motions.Clips.ContainsKey("walk-left")&&c.Skin.Motions.Clips.ContainsKey("walk-right"))Check("左右独立正向步态逐帧驱动位置，各自落稳时不跳回",delegate{
            c.Habits.Interrupt();c.Skin.Motion.Cancel();for(int i=0;i<1000&&c.Skin.Motion.Active;i++)c.Skin.Motion.Tick(.05);c.Pet.MoveForPlay(0);
            var area=SystemParameters.WorkArea;c.Pet.Left=area.Left+(area.Width-c.Pet.Width)/2;c.Pet.Top=area.Top+Math.Max(12,(area.Height-c.Pet.Height)/2);
            foreach(string id in new[]{"walk-left","walk-right"}){var clip=c.Skin.Motions.Clips[id];double startX=c.Pet.Left,startY=c.Pet.Top;c.Skin.Motion.Start(clip,clip.Seconds);int ticks=0;
                while(c.Skin.Motion.Active&&ticks++<3000){c.Skin.Motion.Tick(1.0/60);c.Pet.MoveForPlay(1.0/60);if(c.Skin.Motion.Active){int frame=c.Skin.Motion.FrameIndex;Assert(Math.Abs(c.Pet.Left-(startX+clip.Spec.travelX[frame]*c.Settings.Size/256))<.001,"步态与窗口水平位移不同步");Assert(Math.Abs(c.Pet.Top-(startY+clip.Spec.travelY[frame]*c.Settings.Size/256))<.001,"裁切补偿与窗口垂直位移不同步");}}
                Assert(ticks<3000,"步态未完成");Assert(Math.Abs(c.Pet.Left-(startX+clip.Spec.travelX[clip.Spec.frames-1]*c.Settings.Size/256))<.001,"落稳时水平跳回");
                Assert(Math.Abs(c.Pet.Top-(startY+clip.Spec.travelY.Last()*c.Settings.Size/256))<.001,"落稳时垂直跳回");
                Assert((id=="walk-right"?1:-1)*(c.Pet.Left-startX)>0,"实际移动方向错误");
            }Assert(c.Skin.Motions.Clips["walk-left"].Spec.sheet!=c.Skin.Motions.Clips["walk-right"].Spec.sheet,"左右仍然共用倒放步态");
        });
        if(c.Skin.Motions.Clips.ContainsKey("walk-left"))Check("停在桌面底边仍能迈步，透明窗口边距不会误判为猫越界",delegate{var area=SystemParameters.WorkArea;var clip=c.Skin.Motions.Clips["walk-left"];c.Pet.Left=area.Left+(area.Width-c.Pet.Width)/2;c.Pet.Top=area.Bottom-c.Pet.Height;Assert(c.Pet.HasWalkingRoom(clip.Spec.travelX.Last(),clip.Spec.travelY.Min(),clip.Spec.travelY.Max()),"透明下边距阻止了正常走动");double top=c.Pet.Top;c.Skin.Motion.Start(clip,clip.Seconds);for(int i=0;i<3000&&c.Skin.Motion.Active;i++){c.Skin.Motion.Tick(1.0/60);c.Pet.MoveForPlay(1.0/60);Assert(c.Pet.Top+c.Pet.Surface.PetRect.Top+235*c.Settings.Size/256<=area.Bottom-4+.001,"脚底移出工作区");}Assert(Math.Abs(c.Pet.Top-(top+clip.Spec.travelY.Last()*c.Settings.Size/256))<.001,"底边强行钳制透明窗口导致动作滑动");});
        c.Pet.Close();c.Dispose();
        using(var file=File.Create(Path.Combine(output,"desktop-test-report.json")))new DataContractJsonSerializer(typeof(LivingReport)).WriteObject(file,report);return report.failed==0?0:1;
    }
}
}
